public class Base64_encodeBase64_TriageGen1Test {





    @Test
    public void testEncodeBase64_MaxSizeExceeded() {
        byte[] input = new byte[]{1, 2, 3, 4, 5};
        // Setting maxResultSize to a very small value to trigger IllegalArgumentException
        try {
            Base64.encodeBase64(input, false, false, 1);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Input array too big"));
