package org.apache.commons.codec.binary;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.codec.BinaryDecoder;
import org.apache.commons.codec.BinaryEncoder;
import org.apache.commons.codec.DecoderException;
import org.apache.commons.codec.EncoderException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Base64_encodeBase64_TriageGen1Test {















    @Test
    public void testEncodeBase64_BoundaryMaxSize() {
        byte[] input = new byte[]{1, 2, 3};
        // Calculate a safe maxResultSize. 
        // Base64 expansion is roughly 4/3. 3 bytes -> 4 chars.
        // We set it exactly to a value that should pass to test the boundary.
        int safeSize = 100; 
        byte[] result = Base64.encodeBase64(input, false, false, safeSize);
        assertNotNull(result);
    }
}
